'use strict';
/**
 * scripts/ensure-css.js
 *
 * Runs before `npm start` / `npm run dev`. The stylesheet (public/css/build.css) is generated by Tailwind and is
 * not committed, so a fresh checkout has no CSS and the page loads unstyled with a 404 on /assets/css/build.css.
 * This builds it when it is missing (or older than the source). It never blocks startup: if Tailwind isn't
 * installed (a production install without devDependencies) it prints what to do and continues.
 */
const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const root = path.join(__dirname, '..');
const out = path.join(root, 'public', 'css', 'build.css');
const sources = [path.join(root, 'src', 'css', 'tailwind.css'), path.join(root, 'tailwind.config.js')];

const mtime = (p) => { try { return fs.statSync(p).mtimeMs; } catch { return 0; } };
const stale = !fs.existsSync(out) || sources.some((s) => mtime(s) > mtime(out));
if (!stale) process.exit(0);

console.log('[css] public/css/build.css is missing or out of date: building…');
fs.mkdirSync(path.dirname(out), { recursive: true });
try {
  execSync(`npx --no-install tailwindcss -i ./src/css/tailwind.css -o ./public/css/build.css --minify`, { cwd: root, stdio: 'inherit' });
  console.log('[css] Built public/css/build.css');
} catch {
  console.warn('[css] Could not build the stylesheet. Run `npm install` (Tailwind is a devDependency), then `npm run build`.');
}
